const express = require('express');
const { trace } = require('@opentelemetry/api');

const app = express();
const tracer = trace.getTracer('payment-gateway');
const traceStore = new Map();

app.get('/api/telemetry/spans/:traceId', (req, res) => {
  if (!req.user || !req.user.isPlatformAdmin) {
    return res.status(403).json({ error: 'Platform admin privileges required' });
  }

  const spans = traceStore.get(req.params.traceId);
  if (!spans) {
    return res.status(404).json({ error: 'Trace spans not found' });
  }

  // Enforce tenant boundary and sanitize PCI cardholder data
  const sanitizedSpans = spans
    .filter((s) => s.attributes['tenant.id'] === req.user.tenantId || req.user.role === 'SUPER_ADMIN')
    .map((s) => {
      const safeAttributes = { ...s.attributes };
      delete safeAttributes['payment.card_number'];
      delete safeAttributes['payment.cvv'];
      return {
        name: s.name,
        attributes: safeAttributes,
        timestamp: s.startTime
      };
    });

  if (sanitizedSpans.length === 0) {
    return res.status(403).json({ error: 'Access denied to foreign tenant trace spans' });
  }

  res.json({
    traceId: req.params.traceId,
    spans: sanitizedSpans
  });
});

app.listen(3034);
